hello anybody help ? with some quickly check, I've found that 

```C
find_rawstring_end
```

didn't check line length before accessing it? I'm not sure if vim using c-string internally. anyway following simple patch fix this crash and I'm still checking it worked

```diff
diff --git a/src/nvim/search.c b/src/nvim/search.c
index b105d99d7..4df9ff946 100644
--- a/src/nvim/search.c
+++ b/src/nvim/search.c
@@ -1599,6 +1599,7 @@ static bool find_rawstring_end(char_u *linep, pos_T *startpos, pos_T *endpos)
   char_u *delim_copy;
   size_t delim_len;
   linenr_T lnum;
+  size_t p_len;
 
   for (p = linep + startpos->col + 1; *p && *p != '('; p++) {}
 
@@ -1612,8 +1613,11 @@ static bool find_rawstring_end(char_u *linep, pos_T *startpos, pos_T *endpos)
       if (lnum == endpos->lnum && (colnr_T)(p - line) >= endpos->col) {
         break;
       }
-      if (*p == ')' && p[delim_len + 1] == '"'
-          && STRNCMP(delim_copy, p + 1, delim_len) == 0) {
+
+      p_len = strlen((const char*)p);
+
+      if (*p == ')' && (delim_len + 1 < p_len) && p[delim_len + 1] == '"'
+          && ( 1 < p_len ) && STRNCMP(delim_copy, p + 1, delim_len) == 0) {
         found = true;
         break;
       }

```

maybe second check is not needed

issue.body:
**Describe the bug**
I've hit a crash [here](https://github.com/neovim/neovim/issues/11180), seems that vim have similar code  so maybe it has similar problem (I haven't confirm this)

in src/search.c:1931

```C
static int
find_rawstring_end(char_u *linep, pos_T *startpos, pos_T *endpos)
{
    char_u	*p;
    char_u	*delim_copy;
    size_t	delim_len;
    linenr_T	lnum;
    int		found = FALSE;

    for (p = linep + startpos->col + 1; *p && *p != '('; ++p)
	;
    delim_len = (p - linep) - startpos->col - 1;
    delim_copy = vim_strnsave(linep + startpos->col + 1, delim_len);
    if (delim_copy == NULL)
	return FALSE;
    for (lnum = startpos->lnum; lnum <= endpos->lnum; ++lnum)
    {
	char_u *line = ml_get(lnum);

	for (p = line + (lnum == startpos->lnum
					    ? startpos->col + 1 : 0); *p; ++p)
	{
	    if (lnum == endpos->lnum && (colnr_T)(p - line) >= endpos->col)
		break;
	    if (*p == ')' && p[delim_len + 1] == '"' //<- didn't check if delim_len+1 exceeds strlen(p)
			  && STRNCMP(delim_copy, p + 1, delim_len) == 0) 
	    {
		found = TRUE;
		break;
	    }
	}
	if (found)
	    break;
    }
    vim_free(delim_copy);
    return found;
}
```
